223	            spi_clk => spi_clk_in,
224	            rst_n => rst_n,
225	            serial_data_in => serial_data_in,
226	            spi_chip_select_n => spi_chip_select_n_internal,
227	            rx_data => rx_data,
228	            rx_data_valid => rx_data_valid
229	        );
