1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     This pkg contains utility functions and constants used in the project.
4	--! @details:
5	--!
6	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
7	--!
8	
9	library ieee;
10	use ieee.std_logic_1164.all;
11	use ieee.numeric_std.all;
12	
13	package spi_pkg is
14	    generic (
15	        DATA_WIDTH: natural;
16	        MSB_FIRST_AND_NOT_LSB: boolean
17	    );
18	
19	    subtype data_range_t is natural range 0 to DATA_WIDTH - 1;
20	
21	    function active_edge_chip_select_n_assertion(signal clk_in: std_ulogic; clk_polarity: bit) return boolean;
22	    function active_edge_chip_select_n_deassertion(signal clk_in: std_ulogic; clk_polarity: bit) return boolean;
23	    function tx_active_edge(signal clk_in: std_ulogic; clk_polarity, clk_phase: bit) return boolean;
24	    function rx_active_edge(signal clk_in: std_ulogic; clk_polarity, clk_phase: bit) return boolean;
25	    function last_bit_index(bit_index: data_range_t) return boolean;
26	    procedure reset_bit_index(bit_index: inout data_range_t);
27	    procedure update_bit_index(bit_index: inout data_range_t);
28	end package;
29	
30	package body spi_pkg is
31	    -- See the table: https://en.wikipedia.org/wiki/Serial_Peripheral_Interface#Mode_numbers
32	
33	    function active_edge_chip_select_n_assertion(signal clk_in: std_ulogic; clk_polarity: bit) return boolean is begin
34	        case clk_polarity is
35	            when '0' =>
36	                return falling_edge(clk_in);
37	            when '1' =>
38	                return true;
39	        end case;
40	    end function;
41	
42	    function active_edge_chip_select_n_deassertion(signal clk_in: std_ulogic; clk_polarity: bit) return boolean is begin
43	        case clk_polarity is
44	            when '0' =>
45	                return rising_edge(clk_in);
46	            when '1' =>
47	                return falling_edge(clk_in);
48	        end case;
49	    end function;
50	
51	    function tx_active_edge(signal clk_in: std_ulogic; clk_polarity, clk_phase: bit) return boolean is begin
52	        case clk_polarity & clk_phase is
53	            when "00" | "11" =>
54	                return falling_edge(clk_in);
55	            when "01" =>
56	                return rising_edge(clk_in);
57	            when "10" =>
58	                return true;
59	        end case;
60	    end function;
61	
62	    function rx_active_edge(signal clk_in: std_ulogic; clk_polarity, clk_phase: bit) return boolean is begin
63	        case clk_polarity & clk_phase is
64	            when "00" =>
65	                return rising_edge(clk_in);
66	            when "01" =>
67	                return falling_edge(clk_in);
68	            when "10" =>
69	                return rising_edge(clk_in);
70	            when "11" =>
71	                return falling_edge(clk_in);
72	            when others =>
73	                return false; -- Default case, should not happen
74	        end case;
75	    end function;
76	
77	    function last_bit_index(bit_index: data_range_t) return boolean is begin
78	        if MSB_FIRST_AND_NOT_LSB then
79	            return bit_index = bit_index'subtype'low;
80	        else
81	            return bit_index = bit_index'subtype'high;
82	        end if;
83	    end function;
84	
85	    procedure reset_bit_index(bit_index: inout data_range_t) is begin
86	        bit_index := bit_index'subtype'high when MSB_FIRST_AND_NOT_LSB else bit_index'subtype'low;
87	    end procedure;
88	
89	    procedure update_bit_index(bit_index: inout data_range_t) is begin
90	        if last_bit_index(bit_index) then
91	            reset_bit_index(bit_index);
92	            return;
93	        end if;
94	
95	        bit_index := bit_index - 1 when MSB_FIRST_AND_NOT_LSB else bit_index + 1;
96	    end procedure;
97	end package body;
