30	    constant ROM_DEPTH: natural := 2**address'length;
31	    subtype rom_depth_t is natural range 0 to ROM_DEPTH - 1;
32	
33	    impure function load_rom(path: string) return rom_t is
34	        file instructions_file: text;
35	        variable address: rom_depth_t;
36	        variable rom_reg: rom_t(rom_depth_t)(q'range) := (others => (others => '0'));
