1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     Unit tests for the SPI TX module.
4	--!
5	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
6	--!
7	
8	-- vunit: run_all_in_same_sim
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	use ieee.math_real.all;
14	
15	library vunit_lib;
16	context vunit_lib.vunit_context;
17	
18	library osvvm;
19	use osvvm.RandomPkg.RandomPType;
20	
21	use work.tb_utils.all;
22	use work.utils_pkg.all;
23	
24	
25	entity tb_spi_tx is
26	    generic (
27	        runner_cfg: string := runner_cfg_default;
28	        tb_path: string
29	    );
30	end entity;
31	
32	architecture tb of tb_spi_tx is
33	    -------------------------------------------------------------
34	    -- Internal tb signals/constants
35	    -------------------------------------------------------------
36	    constant PROPAGATION_TIME: time := 1 ns;
37	    constant SIMULATION_TIMEOUT_TIME: time := 1 ms;
38	    constant ENABLE_DEBUG_PRINT: boolean := false;
39	
40	    constant SYS_CLK_FREQUENCY: real := real(50e6);
41	    constant SYS_CLK_PHASE: time := 0 fs;
42	
43	    signal spi_clk_enable: std_ulogic := '1';
44	    signal simulation_done: boolean := false;
45	    -------------------------------------------------------------
46	
47	    -------------------------------------------------------------
48	    -- DuT signals, constants
49	    -------------------------------------------------------------
50	    constant SPI_CLK_POLARITY: bit := '0';
51	    constant SPI_CLK_PHASE: bit := '0';
52	    constant CONTROLLER_AND_NOT_PERIPHERAL: boolean := true;
53	    constant MSB_FIRST_AND_NOT_LSB: boolean := true;
54	    constant DATA_WIDTH: positive := 8;
55	
56	    package spi_pkg_constrained is new work.spi_pkg
57	        generic map (
58	            DATA_WIDTH => DATA_WIDTH,
59	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB
60	        );
61	    use spi_pkg_constrained.all;
62	
63	    signal spi_clk: std_ulogic := '0';
64	    signal rst_n: std_ulogic := '1';
65	
66	    signal tx_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0) := (others => '0');
67	    signal tx_data_valid: std_ulogic := '0';
68	    signal tx_data_ack: std_ulogic;
69	
70	    signal spi_clk_out: std_ulogic;
71	    signal serial_data_out: std_logic;
72	    signal spi_chip_select_n: std_ulogic;
73	
74	    signal tx_is_ongoing: std_ulogic;
75	    -------------------------------------------------------------
76	begin
77	    ------------------------------------------------------------
78	    -- CLOCK Generation
79	    ------------------------------------------------------------
80	    generate_advanced_clock(spi_clk, SYS_CLK_FREQUENCY, SYS_CLK_PHASE, spi_clk_enable);
81	    ------------------------------------------------------------
82	
83	    ------------------------------------------------------------
84	    -- VUnit
85	    ------------------------------------------------------------
86	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
87	
88	    main: process
89	    begin
90	        test_runner_setup(runner, runner_cfg);
91	        info("Starting tb_spi_tx");
92	
93	        if ENABLE_DEBUG_PRINT then
94	            show(display_handler, debug);
95	        end if;
96	
97	        wait until simulation_done;
98	        info("Simulation done, all tests passed!" & LF);
99	
100	        test_runner_cleanup(runner);
101	        wait;
102	    end process;
103	    ------------------------------------------------------------
104	
105	    ------------------------------------------------------------
106	    -- Checker
107	    ------------------------------------------------------------
108	    checker: process
109	        variable random: RandomPType;
110	        variable expected_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
111	
112	        procedure wait_spi_clk_cycles(cycles: natural) is begin
113	            for i in 0 to cycles - 1 loop
114	                wait until rising_edge(spi_clk);
115	            end loop;
116	            wait for PROPAGATION_TIME;
117	        end procedure;
118	
119	        procedure wait_tx_spi_clk_cycles(cycles: natural) is begin
120	            for i in 0 to cycles - 1 loop
121	                wait until tx_active_edge(spi_clk, SPI_CLK_POLARITY, SPI_CLK_PHASE);
122	            end loop;
123	            wait for PROPAGATION_TIME;
124	        end procedure;
125	
126	        procedure wait_chip_select_n_cycles(cycles: natural) is begin
127	            for i in 0 to cycles - 1 loop
128	                wait until active_edge_chip_select_n_assertion(spi_clk, SPI_CLK_POLARITY);
129	            end loop;
130	            wait for PROPAGATION_TIME;
131	        end procedure;
132	
133	        procedure test_reset_behavior is begin
134	            info("1.0) Testing reset behavior");
135	
136	            rst_n <= '1';
137	            tx_data_valid <= '0';
138	            tx_data <= (others => '0');
139	            wait_spi_clk_cycles(1);
140	
